{
  "schema_version": "agentto.spec/v0",
  "name": "Gearbox output bracket",
  "description": "Steel bracket with a rigid gearbox attachment and a 40 N*m torque about +x applied through two end-face drive lugs. Top and bottom are taken along z; lug patches abut the corresponding edges.",
  "units": {
    "length": "mm",
    "force": "N"
  },
  "domain": {
    "kind": "box",
    "size": [160, 80, 80]
  },
  "material": {
    "name": "steel",
    "E": 210000,
    "nu": 0.3
  },
  "volume_fraction": 0.3,
  "supports": [
    {
      "id": "gearbox_attachment",
      "region": {
        "kind": "face",
        "face": "x-"
      },
      "fix": ["x", "y", "z"]
    }
  ],
  "loads": [
    {
      "id": "top_drive_lug",
      "region": {
        "kind": "patch",
        "face": "x+",
        "center": [40, 72],
        "size": [16, 16]
      },
      "force": [0, -625, 0],
      "distribution": "uniform_nodes",
      "note": "Equal and opposite lug forces separated by 64 mm produce 40000 N*mm about +x."
    },
    {
      "id": "bottom_drive_lug",
      "region": {
        "kind": "patch",
        "face": "x+",
        "center": [40, 8],
        "size": [16, 16]
      },
      "force": [0, 625, 0],
      "distribution": "uniform_nodes"
    }
  ],
  "resolution": {
    "h": 2
  }
}
